// Pass-through: parse the raw webhook body (responseData=raw) and forward the envelope.
// HMAC verification DISABLED: n8n's webhook node mangles the raw body, so byte-exact HMAC
// cannot be verified here. Endpoint is loopback-only (127.0.0.1). To re-enable HMAC, put a
// raw-preserving ingress proxy in front of n8n that verifies before forwarding.
const items = $input.all();
const out = [];
for (const item of items) {
  const json = item.json || {};
  const parsed = typeof json.body === 'string' ? JSON.parse(json.body) : json.body;
  out.push({ json: parsed });
}
return out;

const crypto = require('crypto');
const fs = require('fs');
const path = require('path');
const STORE = '/opt/data/projects/wa-hot-lead/store/messages.jsonl';
const storeDir = path.dirname(STORE);
if (!fs.existsSync(storeDir)) { try { fs.mkdirSync(storeDir, { recursive: true }); } catch (e) {} }

const items = $input.all();
const out = [];
for (const item of items) {
  const root = item.json || {};
  const envObj = (typeof root.body === 'string') ? (()=>{ try { return JSON.parse(root.body); } catch(e){ return {}; } })() : (root.body || {});
  const env = Object.keys(envObj).length ? envObj : root;
  const p = env.payload || env;

  // ---- sender / phone extraction ----
  const fromRaw = String(p.from || p.sender || '');
  const isLid = fromRaw.includes('@lid');
  const digitsOnly = fromRaw.split('@')[0].replace(/\D/g, '');
  const isGroup = !!(p.from && String(p.from).endsWith('@g.us')) || !!p.is_group;
  // group messages have no single lead sender -> never Meta-matchable
  const phoneE164 = (!isLid && !isGroup && /^\d{8,16}$/.test(digitsOnly)) ? digitsOnly : '';
  const metaMatchable = Boolean(phoneE164);
  const phoneHash = metaMatchable ? crypto.createHash('sha256').update(phoneE164.trim()).digest('hex') : null;
  const senderDisplay = isGroup ? fromRaw : (isLid ? digitsOnly + '@lid' : phoneE164);

  // ---- message + dedupe + store ----
  const message = String(p.body !== undefined ? p.body : (p.message || ''));
  const direction = p.fromMe ? 'outbound' : 'inbound';
  const ts = p.timestamp ? Number(p.timestamp) : Math.floor(Date.now() / 1000);
  const message_id = String(p.id || p.message_id || (senderDisplay + ':' + ts + ':' + crypto.createHash('sha1').update(message).digest('hex').slice(0, 12)));
  let lines = [];
  try { if (fs.existsSync(STORE)) lines = fs.readFileSync(STORE, 'utf8').split('\n').filter(Boolean); } catch (e) {}
  const dup = lines.some(l => { try { return JSON.parse(l).message_id === message_id; } catch (e) { return false; } });
  if (!dup) {
    try { fs.appendFileSync(STORE, JSON.stringify({ message_id, sender: senderDisplay, message, direction, is_group: isGroup, timestamp: ts, received_at: Date.now(), sender_type: isLid?'lid':'phone', meta_matchable: metaMatchable }) + '\n'); } catch (e) {}
    out.push({ json: { sender: senderDisplay, sender_type: isLid?'lid':'phone', phone_e164: phoneE164, phone_hash_sha256: phoneHash, meta_matchable: metaMatchable, message, direction, is_group: isGroup, timestamp: ts, message_id, is_duplicate: false } });
  }
}
return out;

const fs = require('fs');
const STORE = '/opt/data/projects/wa-hot-lead/store/messages.jsonl' || '/opt/data/projects/wa-hot-lead/store/messages.jsonl';
const items = $input.all();
const out = [];
for (const item of items) {
  const sender = item.json.sender;
  let recs = [];
  try {
    if (fs.existsSync(STORE)) {
      recs = fs.readFileSync(STORE, 'utf8').split('\n').filter(Boolean).map(l => JSON.parse(l));
    }
  } catch (e) {}
  const conv = recs.filter(r => r.sender === sender).sort((a, b) => a.timestamp - b.timestamp).slice(-20);
