const https = require('https');
const fs = require('fs');
const PROMPT = fs.readFileSync('/opt/data/projects/wa-hot-lead/scoring/llm-classify-prompt.md', 'utf8').trim();
const KEY = '${OPENROUTER_API_KEY}';
const PRIMARY = 'nvidia/nemotron-3-ultra-550b-a55b:free';
const FALLBACK = 'nvidia/nemotron-3-super-120b-a12b:free';

function callLLM(model, userContent) {
  return new Promise((resolve, reject) => {
    const payload = JSON.stringify({
      model,
      messages: [
        { role: 'system', content: PROMPT + '\n\nBALAS HANYA JSON valid dengan bentuk: {"lead_level":"hot|warm|cold","score":0-100,"signals":[],"intent":"","reason":""}. Tanpa teks lain.' },
        { role: 'user', content: userContent }
      ],
      response_format: { type: 'json_object' },
      max_tokens: 300, temperature: 0.2
    });
    const req = https.request('https://openrouter.ai/api/v1/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + KEY, 'Content-Length': Buffer.byteLength(payload) }
    }, (res) => {
      let data = '';
      res.on('data', c => data += c);
      res.on('end', () => {
        if (res.statusCode !== 200) { reject(new Error('http ' + res.statusCode)); return; }
        try {
          const j = JSON.parse(data);
          resolve((j.choices && j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '');
        } catch (e) { reject(new Error('bad json')); }
      });
    });
    req.on('error', reject);
    req.setTimeout(25000, () => { req.destroy(new Error('timeout')); });
    req.write(payload); req.end();
  });
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function classify(userContent) {
  // primary with 1 retry
  for (let i = 0; i < 2; i++) {
    try { return { content: await callLLM(PRIMARY, userContent), model: PRIMARY }; } catch (e) { if (i === 0) await sleep(1500); }
  }
  // fallback model
  try { return { content: await callLLM(FALLBACK, userContent), model: FALLBACK }; } catch (e) { return { content: null, model: null }; }
}

const out = [];
for (const item of $input.all()) {
  const msg = item.json.message || '';
  const conv = item.json.conversation ? ('\n\nRiwayat:\n' + item.json.conversation) : '';
  const userContent = msg + conv;
  let level = 'review', score = null, signals = [], intent = '', reason = 'LLM unavailable', usedModel = '';
  const r = await classify(userContent);
  usedModel = r.model || '';
  if (r.content) {
    try {
      const s = r.content.indexOf('{'); const e2 = r.content.lastIndexOf('}');
      const p = JSON.parse(r.content.slice(s, e2 + 1));
      const lvl = (p.lead_level || '').toString().toLowerCase();
      level = ['hot','warm','cold'].includes(lvl) ? lvl : 'review';
      score = Number.isFinite(p.score) ? Math.max(0, Math.min(100, Math.round(p.score))) : null;
      signals = Array.isArray(p.signals) ? p.signals.map(String) : [];
      intent = String(p.intent || '');
      reason = String(p.reason || '');
      if (level === 'review') reason = 'non-conforming output: ' + String(r.content).slice(0, 120);
    } catch (e) { level = 'review'; reason = 'parse error'; }
  }
  out.push({ json: { ...item.json, lead_level: level, score, signals, intent, reason, scorer_model: usedModel } });
}
return out;

const fs = require('fs');
const LEVELS = '/opt/data/projects/wa-hot-lead/store/levels.jsonl';
const out = [];
for (const item of $input.all()) {
  const j = item.json || {};
  // gate: only matchable phones participate in Meta signals
  if (!j.meta_matchable || !j.phone_hash_sha256) continue;
  const newLevel = (j.lead_level || '').toLowerCase();
  if (!['hot','warm','cold'].includes(newLevel)) continue;

  let prev = null;
  try {
    if (fs.existsSync(LEVELS)) {
      const lines = fs.readFileSync(LEVELS, 'utf8').split('\n').filter(Boolean);
      for (let i = lines.length - 1; i >= 0; i--) {
        try { const r = JSON.parse(lines[i]); if (r.phone_hash === j.phone_hash_sha256) { prev = r.level; break; } } catch (e) {}
      }
    }
  } catch (e) {}

  if (prev === newLevel) continue; // no state change -> no event
  try { fs.appendFileSync(LEVELS, JSON.stringify({ phone_hash: j.phone_hash_sha256, level: newLevel, at: Date.now(), message_id: j.message_id }) + '\n'); } catch (e) {}
  out.push({ json: { ...j, event_name: 'Lead' + newLevel.charAt(0).toUpperCase() + newLevel.slice(1), previous_level: prev, level_changed: true } });
}
return out;

