  if (!m || j.direction !== 'outbound') continue;
  const phone = m[1];
  const value = m[2] ? Number(m[2].replace(/[.,]/g,'')) : null;
  const ph = crypto.createHash('sha256').update(phone.trim()).digest('hex');
  // dedupe: same phone closed before?
  let already = false;
  try {
    if (fs.existsSync(CLOSED)) {
      already = fs.readFileSync(CLOSED,'utf8').split('\n').filter(Boolean)
        .some(l => { try { return JSON.parse(l).phone_hash === ph; } catch(e){ return false; } });
    }
  } catch(e){}
  if (already) continue;
  try { fs.appendFileSync(CLOSED, JSON.stringify({ phone_hash: ph, value, at: Date.now(), message_id: j.message_id }) + '\n'); } catch(e){}
  out.push({ json: { ...j, is_purchase: true, phone_hash_sha256: ph, purchase_value: value, event_name: 'Purchase' } });
}
return out;

